import React, { useEffect, useRef } from 'react';
import { portfolioData } from '../../data/portfolioData';
import './Education.css';

const Education = () => {
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -100px 0px' }
    );

    if (sectionRef.current) {
      const revealElements = sectionRef.current.querySelectorAll('.reveal');
      revealElements.forEach((el) => observer.observe(el));
    }
    return () => observer.disconnect();
  }, []);

  const { education } = portfolioData;

  return (
    <section id="education" className="education" ref={sectionRef} aria-labelledby="education-title">
      <div className="container">
        <div className="section-header reveal">
          <span className="section-tag">Academic Background</span>
          <h2 id="education-title" className="section-title">Education</h2>
          <p className="section-subtitle">Strong foundation in engineering principles with specialized focus on mechanical systems and analytical thinking.</p>
        </div>

        <div className="education-timeline reveal stagger-children">
          {education.map((edu, index) => (
            <article key={edu.id} className="education-item" style={{ '--index': index }}>
              <div className="education-marker" aria-hidden="true">
                <div className="marker-dot" />
                <div className="marker-ring" />
                <div className="marker-line" />
              </div>

              <div className="education-card">
                <div className="card-header">
                  <div className="degree-info">
                    <span className="degree-name">{edu.degree}</span>
                    <span className="degree-period">{edu.period}</span>
                  </div>
                  <div className="degree-score">{edu.score}</div>
                </div>

                <div className="card-body">
                  <h3 className="institution-name">{edu.institution}</h3>
                  <p className="institution-detail">
                    {edu.degree === 'B.E Mechanical' && 'Bachelor of Engineering in Mechanical Engineering with focus on design, thermodynamics, and manufacturing processes.'}
                    {edu.degree === 'HSC' && 'Higher Secondary Certificate with Science stream - Physics, Chemistry, Mathematics, and Computer Science.'}
                    {edu.degree === 'SSLC' && 'Secondary School Leaving Certificate with strong foundation in Mathematics and Science.'}
                  </p>
                </div>
              </div>
            </article>
          ))}
        </div>

        {/* Summary Stats */}
        <div className="education-summary reveal">
          <div className="summary-grid">
            <div className="summary-item">
              <div className="summary-icon" aria-hidden="true">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M22 10v6M2 10l10-5 10 5-10 5z" />
                  <path d="M6 12v5c3 3 9 3 12 0v-5" />
                </svg>
              </div>
              <div className="summary-content">
                <span className="summary-value">7.5</span>
                <span className="summary-label">CGPA (B.E)</span>
              </div>
            </div>
            <div className="summary-item">
              <div className="summary-icon" aria-hidden="true">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <circle cx="12" cy="12" r="10" />
                  <path d="M12 6v6l4 2" />
                </svg>
              </div>
              <div className="summary-content">
                <span className="summary-value">79.67%</span>
                <span className="summary-label">HSC Percentage</span>
              </div>
            </div>
            <div className="summary-item">
              <div className="summary-icon" aria-hidden="true">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                  <polyline points="14 2 14 8 20 8" />
                  <line x1="16" y1="13" x2="8" y2="13" />
                  <line x1="16" y1="17" x2="8" y2="17" />
                  <polyline points="10 9 9 9 8 9" />
                </svg>
              </div>
              <div className="summary-content">
                <span className="summary-value">70%</span>
                <span className="summary-label">SSLC Percentage</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Education;
